<script setup lang="ts">
import {computed,ref,watch} from 'vue'
import {useRoute} from 'vue-router'
import {useAuthSessionStore} from '../../stores/authSession'
import {moduleRequest,ModuleApiError} from './api'
import {useCatalogText} from './text'
import {cents,money,displayName} from '../shared-commerce/format'
import type {Category,Product} from './types'
import '../shared-commerce/commerce.css'
const {t,locale}=useCatalogText(),route=useRoute(),auth=useAuthSessionStore(),store=computed(()=>String(route.params.storeId)),base=computed(()=>`/api/v1/stores/${store.value}/catalog`)
const categories=ref<Category[]>([]),products=ref<Product[]>([]),busy=ref(false),error=ref(''),editing=ref<Product|null>(null),showForm=ref(false),categoryEdit=ref<Category|null>(null)
const globalCatalog=computed(()=>auth.user?.roles.includes('tenant_admin')===true)
const can=(permission:string)=>auth.user?.permissions.includes(permission)===true
const category=ref({code:'',nameZh:'',nameEn:'',enabled:true,sortOrder:0})
const blank=()=>({code:'',categoryId:'',nameZh:'',nameEn:'',descriptionZh:'',descriptionEn:'',kind:'physical',unit:'件',imageUrl:'',price:'0.00',taxMode:'inclusive',taxCategory:'not_applicable',taxRate:'0',channels:['cards'] as string[]})
const form=ref(blank());let generation=0;let retry:{path:string;method:string;body:Record<string,unknown>}|null=null
async function run(work:()=>Promise<void>){if(busy.value)return;busy.value=true;error.value='';const g=generation;try{await work()}catch(e){if(g===generation)error.value=e instanceof Error?e.message:String(e)}finally{if(g===generation)busy.value=false}}
async function load(){const g=generation;const [c,p]=await Promise.all([moduleRequest<Category[]>(base.value,'/categories'),moduleRequest<Product[]>(base.value,'/products')]);if(g!==generation)return;categories.value=c;products.value=p}
async function mutate(path:string,body:Record<string,unknown>,method='POST'){retry={path,method,body:{...body,idempotencyKey:crypto.randomUUID()}};try{await moduleRequest(base.value,path,method,retry.body)}catch(e){if(e instanceof ModuleApiError&&e.status<500)retry=null;throw e}retry=null;await load()}
function edit(p?:Product){editing.value=p??null;form.value=p?{...p,price:(p.priceCents/100).toFixed(2),taxRate:String(p.taxRate),channels:[...p.channels]}:blank();showForm.value=true}
async function save(){await run(async()=>{if(!globalCatalog.value&&editing.value){await mutate(`/products/${editing.value.id}/listing`,{priceCents:cents(form.value.price),channels:form.value.channels,enabled:editing.value.listingEnabled,expectedVersion:editing.value.listingVersion})}else await mutate(editing.value?`/products/${editing.value.id}`:'/products',{...form.value,priceCents:cents(form.value.price),expectedVersion:editing.value?.version??null},editing.value?'PUT':'POST');showForm.value=false})}
async function saveCategory(){await run(async()=>{await mutate(categoryEdit.value?`/categories/${categoryEdit.value.id}`:'/categories',{...category.value,expectedVersion:categoryEdit.value?.version??null},categoryEdit.value?'PUT':'POST');category.value={code:'',nameZh:'',nameEn:'',enabled:true,sortOrder:0};categoryEdit.value=null})}
watch(store,()=>{generation++;busy.value=false;retry=null;showForm.value=false;products.value=[];categories.value=[];void run(load)},{immediate:true})
</script>
<template><main class="cards-page"><nav><RouterLink :to="`/stores/${store}/wallet/more`">← {{t('back')}}</RouterLink><h1>{{t('catalog')}}</h1><button :disabled="busy" @click="run(load)">{{t('refresh')}}</button></nav><p v-if="error" class="cards-error" role="alert">{{error}}</p><button v-if="retry" :disabled="busy" @click="run(async()=>{if(retry){try{await moduleRequest(base,retry.path,retry.method,retry.body)}catch(e){if(e instanceof ModuleApiError&&e.status<500)retry=null;throw e}retry=null;await load()}})">{{t('recover')}}</button><p v-if="busy" role="status">{{t('loading')}}</p>
<section class="cards-panel"><h2>{{t('category')}}</h2><div class="cards-actions"><button v-for="c in categories" :key="c.id" :disabled="!can('catalog.manage')||busy" @click="categoryEdit=c;category={code:c.code,nameZh:c.nameZh,nameEn:c.nameEn,enabled:c.enabled,sortOrder:c.sortOrder}">{{displayName(c,locale)}} · {{c.enabled?'✓':'—'}}</button></div><form v-if="globalCatalog&&can('catalog.manage')" @submit.prevent="saveCategory"><div class="cards-grid"><label>{{t('code')}}<input v-model="category.code" required :disabled="!!categoryEdit" maxlength="80"></label><label>{{t('nameZh')}}<input v-model="category.nameZh"></label><label>{{t('nameEn')}}<input v-model="category.nameEn"></label><label class="check"><input v-model="category.enabled" type="checkbox">{{t('active')}}</label></div><div class="cards-actions"><button :disabled="busy||!!retry">{{t('save')}}</button></div></form></section>
<section class="cards-panel"><div class="cards-actions"><h2>{{t('product')}}</h2><button v-if="globalCatalog&&can('catalog.manage')" :disabled="busy" @click="edit()">＋ {{t('create')}}</button></div><form v-if="showForm" @submit.prevent="save"><fieldset :disabled="!globalCatalog" style="border:0;padding:0;margin:0"><div class="cards-grid"><label>{{t('code')}}<input v-model="form.code" required maxlength="80" :disabled="!!editing"></label><label>{{t('category')}}<select v-model="form.categoryId" required><option value="">{{t('select')}}</option><option v-for="c in categories" :key="c.id" :value="c.id">{{displayName(c,locale)}}</option></select></label><label>{{t('nameZh')}}<input v-model="form.nameZh"></label><label>{{t('nameEn')}}<input v-model="form.nameEn"></label><label>{{t('descriptionZh')}}<textarea v-model="form.descriptionZh" /></label><label>{{t('descriptionEn')}}<textarea v-model="form.descriptionEn" /></label><label>{{t('kind')}}<select v-model="form.kind"><option value="physical">{{t('physical')}}</option><option value="service">{{t('service')}}</option></select></label><label>{{t('unit')}}<input v-model="form.unit" required></label><label>{{t('image')}}<input v-model="form.imageUrl"></label></div></fieldset><div class="cards-grid"><label>{{t('price')}}<input v-model="form.price" inputmode="decimal" required></label><label>{{t('inclusive')}} / {{t('exclusive')}}<select v-model="form.taxMode" :disabled="!globalCatalog"><option value="inclusive">{{t('inclusive')}}</option><option value="exclusive">{{t('exclusive')}}</option></select></label><label>{{t('taxCategory')}}<select v-model="form.taxCategory" :disabled="!globalCatalog" @change="form.taxCategory!=='taxable'&&(form.taxRate='0')"><option v-for="v in ['taxable','zero','exempt','not_applicable']" :key="v" :value="v">{{t(v)}}</option></select></label><label>{{t('taxRate')}}<input v-model="form.taxRate" :disabled="!globalCatalog||form.taxCategory!=='taxable'" inputmode="decimal"></label></div><p class="cards-muted">{{t('taxHint')}}</p><div class="cards-actions"><span>{{t('channels')}}</span><label v-for="v in ['cards','rewards','shopping','storage']" :key="v" class="check"><input v-model="form.channels" type="checkbox" :value="v">{{t(v)}}</label></div><div class="cards-actions"><button class="primary" :disabled="busy||!!retry">{{t('save')}}</button><button type="button" @click="showForm=false">{{t('cancel')}}</button></div></form>
<p v-if="!products.length&&!busy">{{t('empty')}}</p><div class="cards-grid"><article v-for="p in products" :key="p.id" class="cards-panel"><h3>{{displayName(p,locale)}}</h3><small>{{p.code}} · {{t(p.status)}}</small><p>{{money(p.priceCents)}} / {{p.unit}} · {{t(p.taxMode)}}</p><p>{{p.channels.map(c=>t(c)).join(' · ')}}</p><div class="cards-actions"><button v-if="can('catalog.manage')&&p.status!=='archived'" :disabled="busy" @click="edit(p)">{{t('edit')}}</button><button v-if="can('catalog.manage')" :disabled="busy||!!retry" @click="run(()=>mutate(`/products/${p.id}/listing`,{priceCents:p.priceCents,channels:p.channels,enabled:!p.listingEnabled,expectedVersion:p.listingVersion}))">{{t(p.listingEnabled?'storeOff':'storeOn')}}</button><template v-if="globalCatalog&&can('catalog.publish')&&p.status!=='archived'"><button v-for="state in ['active','inactive','archived'].filter(s=>s!==p.status)" :key="state" :disabled="busy||!!retry" @click="run(()=>mutate(`/products/${p.id}/status`,{status:state,expectedVersion:p.version}))">{{t(state)}}</button></template></div></article></div></section></main></template>
